mapper.select:
SELECT store_id, store_name, category, region, address, phone, latitude, longitude, image_path, created_at
FROM store
WHERE store_id = #{storeId}

sql.where:
AND s.region LIKE '부산%'

    AND s.store_name LIKE CONCAT('%', #{keyword}, '%')


    AND s.region = #{region}


    AND s.category = #{category}

mapper.select:
SELECT s.store_id, s.store_name, s.category, s.region, s.address, s.image_path,
       ROUND(AVG(r.rating), 1) AS avg_rating,
       COUNT(r.review_id)      AS review_count,
       (SELECT r2.title FROM review r2 WHERE r2.store_id = s.store_id
        ORDER BY r2.created_at DESC LIMIT 1) AS one_liner
FROM store s
JOIN review r ON s.store_id = r.store_id
WHERE s.region = #{region}

    AND s.store_name NOT REGEXP #{franchisePattern}

GROUP BY s.store_id, s.store_name, s.category, s.region, s.address, s.image_path
HAVING AVG(r.rating) >= #{minRating}
ORDER BY avg_rating DESC, review_count DESC, s.store_id
LIMIT #{limit}

SELECT s.store_id, s.store_name, s.category, s.region, s.address, s.image_path, s.latitude, s.longitude, ROUND(AVG(r.rating), 1) AS avg_rating, COUNT(r.review_id) AS review_count, (SELECT r2.title FROM review r2 WHERE r2.store_id = s.store_id ORDER BY r2.created_at DESC LIMIT 1) AS one_liner FROM store s LEFT JOIN review r ON s.store_id = r.store_id WHERE s.region = #{region}
AND s.category IN
#{cat}
AND s.store_id NOT IN
#{ex}
AND s.store_name NOT REGEXP #{franchisePattern}
GROUP BY s.store_id, s.store_name, s.category, s.region, s.address, s.image_path, s.latitude, s.longitude
HAVING AVG(r.rating) >= #{minRating}
ORDER BY RAND(#{seed}) LIMIT 1
